package io.github.diodeme.ji.testkit;

import com.fasterxml.jackson.databind.JsonNode;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.CancellationException;

/** Deterministic script interpreter for provider-independent contract tests. */
public final class FauxProvider {
    private final DynamicClock clock;
    private final FixedIdGenerator ids;

    public FauxProvider(DynamicClock clock, FixedIdGenerator ids) {
        this.clock = Objects.requireNonNull(clock, "clock");
        this.ids = Objects.requireNonNull(ids, "ids");
    }

    public FauxResponse execute(JsonNode script, Signal signal, Cancellation cancellation) {
        Objects.requireNonNull(script, "script");
        var chunks = new ArrayList<FauxChunk>();
        for (JsonNode step : script.path("steps")) {
            cancellation.throwIfCancelled();
            String type = step.path("type").asText();
            switch (type) {
                case "text", "thinking" -> chunks.add(new FauxChunk(type, step.path("value").asText(), ids.next()));
                case "tool_call" -> chunks.add(new FauxChunk(type,
                        step.path("name").asText() + ":" + step.path("arguments").toString(), ids.next()));
                case "malformed_tool_call" -> chunks.add(new FauxChunk(type,
                        step.path("name").asText() + ":" + step.path("argumentsText").asText(), ids.next()));
                case "wait" -> signal.await(step.path("signal").asText());
                case "delay" -> clock.advance(Duration.ofMillis(step.path("millis").asLong()));
                case "error" -> throw new FauxProviderException(
                        step.path("code").asText(), step.path("retryAfterMillis").asLong(0));
                case "abort" -> throw new CancellationException("faux provider aborted by script");
                default -> throw new IllegalArgumentException("unknown faux step: " + type);
            }
        }
        JsonNode usage = script.path("usage");
        return new FauxResponse(
                script.path("responseId").asText(),
                List.copyOf(chunks),
                usage.path("inputTokens").asLong(),
                usage.path("outputTokens").asLong(),
                usage.path("costMicros").asLong(),
                clock.instant());
    }

    public record FauxChunk(String type, String value, String id) {}

    public record FauxResponse(
            String responseId,
            List<FauxChunk> chunks,
            long inputTokens,
            long outputTokens,
            long costMicros,
            java.time.Instant completedAt) {}

    @FunctionalInterface
    public interface Signal {
        void await(String name);
    }

    @FunctionalInterface
    public interface Cancellation {
        boolean isCancelled();

        default void throwIfCancelled() {
            if (isCancelled()) {
                throw new CancellationException("faux provider request cancelled");
            }
        }
    }

    public static final class FauxProviderException extends RuntimeException {
        private static final long serialVersionUID = 1L;
        private final String code;
        private final long retryAfterMillis;

        public FauxProviderException(String code, long retryAfterMillis) {
            super(code);
            this.code = code;
            this.retryAfterMillis = retryAfterMillis;
        }

        public String code() {
            return code;
        }

        public long retryAfterMillis() {
            return retryAfterMillis;
        }
    }
}
